<?php ob_start(); ?><h1><?= e(t('Suspicious logs')) ?></h1><form><input class="input" name="ip" placeholder="IP" value="<?= e($_GET['ip']??'') ?>"> <input class="input" name="uri" placeholder="<?= e(t('URI contains')) ?>" value="<?= e($_GET['uri']??'') ?>"> <input class="input" name="site" placeholder="<?= e(t('Site')) ?>" value="<?= e($_GET['site']??'') ?>"> <select class="input" name="risk"><option value=""><?= e(t('Any risk')) ?></option><?php foreach(['low','medium','high','critical'] as $r): ?><option value="<?= e($r) ?>" <?= ($_GET['risk']??'')===$r?'selected':'' ?>><?= e(t($r)) ?></option><?php endforeach ?></select> <input class="input" name="type" placeholder="<?= e(t('Type')) ?>" value="<?= e($_GET['type']??'') ?>"> <input class="input" type="date" name="date_from" value="<?= e($_GET['date_from']??'') ?>"> <input class="input" type="date" name="date_to" value="<?= e($_GET['date_to']??'') ?>"> <button class="btn"><?= e(t('Filter')) ?></button> <a class="btn" href="/logs/export.csv?<?= e(http_build_query($_GET)) ?>"><?= e(t('Export CSV')) ?></a></form><table><tr><th><?= e(t('Risk')) ?></th><th><?= e(t('Type')) ?></th><th><?= e(t('Site')) ?></th><th>IP</th><th><?= e(t('Method')) ?></th><th><?= e(t('URI')) ?></th><th><?= e(t('Status')) ?></th><th><?= e(t('User agent')) ?></th><th><?= e(t('Referer')) ?></th><th><?= e(t('Raw')) ?></th></tr><?php $threatIps=$threatIps??[]; foreach($events as $l): $ti=$threatIps[$l['ip']]??null; ?><tr><td><span class="badge <?= e($l['risk']) ?>"><?= e(t($l['risk'])) ?></span></td><td><?= e($l['event_type']) ?></td><td><?= e($l['site_name'] ?? '') ?></td><td><?= e($l['ip']) ?> <?php if($ti): ?><span class="badge <?= e($ti['risk']) ?>" title="<?= e(t($ti['classification'])) ?>"><?= e(t($ti['classification'])) ?></span><?php else: ?><a class="btn small" href="/threat-ips?ip=<?= urlencode($l['ip']) ?>"><?= e(t('Flag IP')) ?></a><?php endif ?></td><td><?= e($l['method']) ?></td><td class="uri-cell"><span title="<?= e($l['uri']) ?>"><?= e(mb_strimwidth($l['uri']??'',0,120,'…')) ?></span></td><td><?= e($l['status_code']) ?></td><td><?= e(mb_strimwidth($l['user_agent']??'',0,80,'…')) ?></td><td><?= e($l['referer']) ?></td><td><pre><?= e(mb_strimwidth($l['raw_line'],0,500,'…')) ?></pre></td></tr><?php endforeach ?></table><?php $content=ob_get_clean(); include base_path('resources/views/layouts/app.php'); ?>
